solution.solution.cpp:
template <typename Derived>
struct Comparable
{
    friend bool operator!=(const Derived& a, const Derived& b) { return !(a == b); }
    friend bool operator>(const Derived& a, const Derived& b) { return b < a; }
    friend bool operator<=(const Derived& a, const Derived& b) { return !(b < a); }
    friend bool operator>=(const Derived& a, const Derived& b) { return !(a < b); }
};

unitTests:
struct Version : Comparable<Version>
{
    int major{}, minor{};
    friend bool operator==(const Version& a, const Version& b) { return a.major == b.major && a.minor == b.minor; }
    friend bool operator<(const Version& a, const Version& b) { return a.major != b.major ? a.major < b.major : a.minor < b.minor; }
};
struct Height : Comparable<Height>
{
    double cm{};
    friend bool operator==(const Height& a, const Height& b) { return a.cm == b.cm; }
    friend bool operator<(const Height& a, const Height& b) { return a.cm < b.cm; }
};
Version v(int a, int b) { Version x; x.major = a; x.minor = b; return x; }
Height h(double cm) { Height x; x.cm = cm; return x; }

TEST("the four derived operators") { CHECK(v(1, 2) != v(1, 3)); CHECK(!(v(1, 2) != v(1, 2))); CHECK(v(2, 0) > v(1, 9)); CHECK(v(1, 2) <= v(1, 2)); CHECK(v(1, 2) <= v(1, 3)); CHECK(v(1, 3) >= v(1, 2)); CHECK(!(v(1, 2) >= v(2, 0))); }
TEST("it works for any class that opts in") { CHECK(h(180) > h(170)); CHECK(h(170) != h(171)); CHECK(h(5) >= h(5)); }
TEST("and adds nothing to the object's size") { CHECK_EQ(sizeof(Height), sizeof(double)); }

